// Demo: Signature Hybrid X25519+Kyber — hybrid secret mixing
function mix(a,b){var h=0;var s=a+b;for(var i=0;i<s.length;i++){h=(h*33+s.charCodeAt(i))>>>0;}return h.toString(16);}
var hybrid=mix('x25519-secret-3','kyber-secret-16');
console.log('technique: Signature Hybrid X25519+Kyber');console.log('hybrid secret: '+hybrid);
console.log('attacker must break BOTH to recover the secret');

